const sharedSecret = 'GANTI_DENGAN_SECRET_ACAK_MINIMAL_32_KARAKTER';
const appUrl = 'https://geo.griyaquran.web.id';
const n8nApiKey = 'ISI_N8N_API_KEY_APLIKASI_DI_SINI';
const emailFrom = 'ISI_EMAIL_PENGIRIM_DI_SINI';

const incoming = $input.first()?.json ?? {};
const headers = incoming.headers ?? {};
const suppliedSecret = String(headers['x-geopresensi-secret'] ?? headers['X-GeoPresensi-Secret'] ?? '');
const body = incoming.body ?? incoming;
const userId = Number(body.user_id);
const periodStart = String(body.period_start ?? '').trim();
const normalizedAppUrl = String(appUrl).trim().replace(/\/+$/, '').replace(/\/api$/i, '');

if (sharedSecret.startsWith('GANTI_') || sharedSecret.length < 32) throw new Error('Isi sharedSecret dengan N8N_MONTHLY_PERFORMANCE_WEBHOOK_SECRET backend.');
if (suppliedSecret !== sharedSecret) throw new Error('Secret webhook GeoPresensi tidak cocok.');
if (!Number.isSafeInteger(userId) || userId <= 0) throw new Error('user_id guru tidak valid.');
if (periodStart.length !== 10 || !periodStart.endsWith('-01')) throw new Error('period_start harus berformat YYYY-MM-01.');
if (!normalizedAppUrl.startsWith('https://')) throw new Error('appUrl harus menggunakan HTTPS.');
if (!n8nApiKey || n8nApiKey.startsWith('ISI_')) throw new Error('Isi n8nApiKey dengan N8N_API_KEY backend.');
if (!String(emailFrom).includes('@') || emailFrom.startsWith('ISI_')) throw new Error('Isi emailFrom dengan alamat pengirim SMTP.');

return [{ json: { appUrl: normalizedAppUrl, n8nApiKey, emailFrom, userId, periodStart } }];

const response = $input.first()?.json ?? {};
if (response.success !== true) throw new Error(response.message || 'Laporan performa tidak berhasil dimuat dari GeoPresensi.');
const report = response.data ?? {};
const teacher = report.teacher ?? {};
const period = report.period ?? {};
const stats = report.summary ?? {};
const rows = Array.isArray(report.rows) ? report.rows : [];
if (!teacher.email || !String(teacher.email).includes('@')) throw new Error('Email guru belum ada atau tidak valid pada profil GeoPresensi.');
if (!teacher.nama) throw new Error('Nama guru tidak tersedia pada laporan.');

const n = (key) => Number(stats[key] ?? 0) || 0;
const late = n('terlambat');
const absent = n('tidakPresensi');
const missingCheckout = n('pulangBelumTercatat');
const piketNoAttendance = n('tanpaPresensiPadaHariPiket');
const piketLate = n('terlambatPadaHariPiket');
const greeting = (teacher.sapaan || 'Ustadz/Ustadzah') + ' ' + teacher.nama;
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const suggestions = [];
if (late > 0) suggestions.push('Mohon berusaha hadir lebih awal agar dapat memulai tugas tepat waktu.');
if (absent > 0) suggestions.push('Jika berhalangan hadir, mohon menyampaikan izin sesuai prosedur agar catatan kehadiran dapat diperbarui.');
if (piketNoAttendance > 0 || piketLate > 0) suggestions.push('Mohon melaksanakan tugas piket sesuai jadwal, hadir tepat waktu pada hari piket, atau berkoordinasi apabila berhalangan.');
if (missingCheckout > 0) suggestions.push('Mohon melengkapi presensi pulang sebelum meninggalkan lokasi kerja.');
if (suggestions.length === 0) suggestions.push('Alhamdulillah, tidak ada catatan perbaikan utama pada indikator ini. Mohon pertahankan kedisiplinan dan konsistensi yang sudah baik.');

const summaryItems = [
  ['Hari kerja', n('hariKerja')],
  ['Hadir', n('hadir') + ' (' + n('persentaseKehadiran') + '%)'],
  ['Tepat waktu', n('tepatWaktu') + ' (' + n('persentaseTepatWaktu') + '% dari kehadiran)'],
  ['Terlambat', late],
  ['Izin', n('izin')],
  ['Sakit', n('sakit')],
  ['Tidak ada presensi', absent],
  ['Pulang belum tercatat', missingCheckout],
  ['Presensi pada hari piket', n('hadirPadaHariPiket') + ' dari ' + n('hariPiketTerjadwal')]
];
const summaryRows = summaryItems.map(([label, value]) =>
  '<tr><th style="padding:9px 12px;border:1px solid #dbe3ee;background:#f8fafc;text-align:left;font-weight:600">' +
  esc(label) + '</th><td style="padding:9px 12px;border:1px solid #dbe3ee">' + esc(value) + '</td></tr>'
).join('');

const labels = {
  hadir: 'Hadir tepat waktu',
  hadir_terlambat: 'Hadir terlambat',
  hadir_izin_terlambat: 'Hadir terlambat dengan izin',
  izin: 'Izin',
  sakit: 'Sakit',
  alfa: 'Tidak ada presensi',
  libur: 'Hari non-kerja',
  libur_override: 'Libur khusus'
};
const detailRows = rows.map((row) => {
  const status = labels[row.status] || row.status || '—';
  const piket = row.piketTerjadwal ? row.statusPiket : '—';
  return '<tr>' +
    '<td style="padding:8px;border:1px solid #dbe3ee;white-space:nowrap">' + esc(row.tanggal || '—') + '</td>' +
    '<td style="padding:8px;border:1px solid #dbe3ee">' + esc(row.hari || '—') + '</td>' +
    '<td style="padding:8px;border:1px solid #dbe3ee">' + esc(status) + '</td>' +
    '<td style="padding:8px;border:1px solid #dbe3ee;white-space:nowrap">' + esc(row.jamMasuk || '—') + '</td>' +
    '<td style="padding:8px;border:1px solid #dbe3ee;white-space:nowrap">' + esc(row.jamPulang || '—') + '</td>' +
    '<td style="padding:8px;border:1px solid #dbe3ee">' + esc(piket) + '</td>' +
  '</tr>';
}).join('') || '<tr><td colspan="6" style="padding:8px;border:1px solid #dbe3ee">Rincian harian tidak tersedia.</td></tr>';

const suggestionsHtml = suggestions.map((item) => '<li style="margin:6px 0">' + esc(item) + '</li>').join('');
const salutation = esc(teacher.sapaan || 'Ustadz/Ustadzah');
const safeGreeting = esc(greeting);
const html =
  '<!doctype html><html><body style="margin:0;padding:24px;background:#f1f5f9;font-family:Arial,sans-serif;color:#1f2937;line-height:1.55">' +
  '<div style="max-width:900px;margin:0 auto;background:#ffffff;padding:24px;border:1px solid #e2e8f0;border-radius:12px">' +
  '<p>Assalamu’alaikum ' + safeGreeting + ',</p>' +
  '<p>Jazakumullahu khaira katsira atas kerja keras ' + safeGreeting + ' selama sebulan terakhir ini. Semoga usaha dan kerja keras ' + safeGreeting + ' dibalas dengan balasan terbaik oleh Allah ta’ala.</p>' +
  '<p>Berikut laporan personal performa presensi periode <strong>' + esc(period.label || 'Bulanan') + '</strong>. Laporan ini berdasarkan catatan aplikasi GeoPresensi dan snapshot rekap yang telah ' + salutation + ' setujui.</p>' +
  '<h3 style="margin:22px 0 8px">Ringkasan Performa</h3>' +
  '<table role="presentation" style="width:100%;max-width:620px;border-collapse:collapse;margin-bottom:22px"><tbody>' + summaryRows + '</tbody></table>' +
  '<h3 style="margin:22px 0 8px">Rincian Presensi Harian</h3>' +
  '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr style="background:#eff6ff">' +
  '<th style="padding:8px;border:1px solid #dbe3ee;text-align:left">Tanggal</th>' +
  '<th style="padding:8px;border:1px solid #dbe3ee;text-align:left">Hari</th>' +
  '<th style="padding:8px;border:1px solid #dbe3ee;text-align:left">Status</th>' +
  '<th style="padding:8px;border:1px solid #dbe3ee;text-align:left">Jam masuk</th>' +
  '<th style="padding:8px;border:1px solid #dbe3ee;text-align:left">Jam pulang</th>' +
  '<th style="padding:8px;border:1px solid #dbe3ee;text-align:left">Jadwal piket</th>' +
  '</tr></thead><tbody>' + detailRows + '</tbody></table></div>' +
  '<h3 style="margin:22px 0 8px">Saran dengan Hormat</h3><ul style="padding-left:22px">' + suggestionsHtml + '</ul>' +
  '<p>Terima kasih atas dedikasi dan kerja keras ' + safeGreeting + '. Semoga Allah ta’ala memudahkan ikhtiar kita untuk terus memperbaiki pelayanan dan kedisiplinan.</p>' +
  '<p style="font-size:13px;color:#64748b">Jika ada catatan yang menurut Ustadz/Ustadzah belum sesuai, silakan sampaikan kepada admin sekolah untuk ditinjau.</p>' +
  '<p>Wassalamu’alaikum,<br><strong>Sistem GeoPresensi Griya Quran</strong></p>' +
  '</div></body></html>';

const emailFrom = $items('Validasi Event & Konfigurasi')[0]?.json?.emailFrom;
return [{ json: { toEmail: teacher.email, fromEmail: emailFrom, subject: 'Laporan Performa Presensi ' + (period.label || 'Bulanan'), html } }];
